import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue accepts without blocking.

    Creates a queue.Queue of capacity cap and tries to put each element of xs
    in order with put_nowait. Stops at the first element rejected because the
    queue is full, and returns the number of puts accepted before that point.
    Nothing is ever taken out of the queue. A capacity of zero or less
    accepts nothing (it is not treated as unbounded).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_more_items_than_capacity() -> None:
    assert accepted(3, [1, 2, 3, 4, 5]) == 3


def test_fewer_items_than_capacity() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_exact_fit() -> None:
    assert accepted(4, [9, 8, 7, 6]) == 4


def test_empty_input() -> None:
    assert accepted(5, []) == 0


def test_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity() -> None:
    assert accepted(-2, [1, 2]) == 0


def test_duplicates_and_negatives_are_counted() -> None:
    assert accepted(3, [7, 7, -1, 7, 7]) == 3


def test_capacity_one() -> None:
    assert accepted(1, [42, 43]) == 1


def test_large_input() -> None:
    assert accepted(100, list(range(1000))) == 100
